
:root {
  --bg: #030407;
  --surface: #080D18;
  --surface-2: #0B1530;
  --line: rgba(137,164,205,.16);
  --text: #f4f6fb;
  --muted: #A6B4C8;
  --accent: #D4FF24;
  --accent-2: #1558C9;
  --max: 1180px;
  --radius: 22px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: radial-gradient(ellipse at 78% 12%, rgba(21,88,201,.10), transparent 31%), radial-gradient(ellipse at 8% 48%, rgba(21,88,201,.055), transparent 27%), var(--bg);
  color: var(--text);
  font-family: "DM Sans", sans-serif;
  line-height: 1.65;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }
.container { width: min(calc(100% - 48px), var(--max)); margin: 0 auto; }
.noise {
  position: fixed; inset: 0; pointer-events: none; opacity: .035; z-index: 10;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
}
.nav-wrap { position: sticky; top: 0; z-index: 20; backdrop-filter: blur(18px); background: rgba(3,4,7,.88); border-bottom: 1px solid var(--line); }
.nav { height: 76px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.brand {
  width: 40px; height: 40px; border: 1px solid var(--line); border-radius: 12px;
  display: grid; place-items: center; font-weight: 800; letter-spacing: -.05em;
  background: rgba(8,13,24,.76);
}
.nav-links { display: flex; gap: 30px; color: var(--muted); font-size: 14px; }
.nav-links a:hover { color: var(--text); }
.nav-cta { font-size: 14px; font-weight: 700; }
.nav-cta span, .button span { margin-left: 8px; }
.hero {
  min-height: calc(100vh - 76px); display: grid; grid-template-columns: 1.25fr .75fr;
  align-items: center; gap: 80px; padding-top: 70px; padding-bottom: 90px;
}
.eyebrow, .section-label {
  color: var(--accent); text-transform: uppercase; letter-spacing: .16em; font-size: 11px; font-weight: 800;
}
.eyebrow { display: flex; align-items: center; gap: 10px; }
.pulse { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 18px var(--accent); }
h1, h2, h3, h4 { font-family: "Manrope", sans-serif; margin: 0; line-height: 1.08; letter-spacing: -.045em; }
h1 { font-size: clamp(54px, 7vw, 94px); max-width: 900px; margin-top: 24px; }
h1 em { color: var(--accent); font-style: normal; }
.hero-sub { font-weight: 700; font-size: 18px; margin: 28px 0 12px; }
.hero-sub span { color: var(--accent); padding: 0 5px; }
.hero-text { color: var(--muted); max-width: 680px; font-size: 17px; }
.hero-actions { display: flex; gap: 12px; margin-top: 32px; }
.button {
  display: inline-flex; align-items: center; justify-content: center; padding: 13px 19px;
  border-radius: 12px; font-weight: 800; font-size: 14px; border: 1px solid var(--line); transition: .2s ease;
}
.button:hover { transform: translateY(-2px); }
.button-primary { background: var(--accent); color: #091007; border-color: var(--accent); }
.button-ghost { background: rgba(255,255,255,.03); }
.button-light { background: #fff; color: #0b0f19; border-color: #fff; }
.quick-links { display: flex; align-items: center; gap: 10px; margin-top: 25px; color: var(--muted); font-size: 13px; }
.quick-links a { display: inline-flex; align-items: center; gap: 7px; }
.quick-links a:hover { color: var(--text); }
.contact-icon { display: inline-flex; align-items: center; justify-content: center; width: 16px; height: 16px; font-size: 11px; color: var(--accent); }
.hero-card {
  border: 1px solid var(--line); background: linear-gradient(145deg, rgba(255,255,255,.07), rgba(255,255,255,.015));
  border-radius: 28px; padding: 26px; min-height: 430px; display: flex; flex-direction: column;
  justify-content: space-between; box-shadow: 0 30px 100px rgba(0,0,0,.3);
}
.card-top, .job-meta, .footer { display: flex; justify-content: space-between; gap: 20px; }
.card-top { color: var(--muted); font-size: 10px; letter-spacing: .15em; font-weight: 800; }
.orb {
  width: 170px; height: 170px; margin: 20px auto 0; border-radius: 50%; display: grid; place-items: center;
  background: radial-gradient(circle at 35% 30%, #e9ffc9, var(--accent) 32%, #54751f 72%, #1c2910);
  color: #0a1005; font: 800 52px "Manrope"; box-shadow: 0 0 80px rgba(184,255,92,.18);
}
.profile-title { font: 800 30px "Manrope"; margin-top: 28px; }
.hero-card p { color: var(--muted); margin: 6px 0 0; }
.mini-stats { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; margin-top: 28px; }
.mini-stats div { border-top: 1px solid var(--line); padding-top: 13px; }
.mini-stats strong { display: block; font: 800 21px "Manrope"; }
.mini-stats span { color: var(--muted); font-size: 11px; }
.section { padding: 125px 0; }
.section-label { margin-bottom: 38px; }
.about-grid { display: grid; grid-template-columns: .9fr 1.1fr; gap: 100px; }
.about-grid h2, .experience-head h2, .skills-intro h2, .community-grid h2, .contact h2 {
  font-size: clamp(36px, 4.5vw, 60px);
}
.about-copy { color: var(--muted); font-size: 16px; }
.about-copy p { margin: 0 0 22px; }
.impact { border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); background: var(--surface); }
.metrics { display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); }
.metric { padding: 48px 24px; border-right: 1px solid var(--line); }
.metric:first-child { padding-left: 0; }
.metric:last-child { border-right: 0; }
.metric strong { display: block; font: 800 clamp(34px,4vw,54px) "Manrope"; color: var(--accent); letter-spacing: -.06em; }
.metric span { color: var(--muted); display: block; margin-top: 8px; max-width: 180px; font-size: 13px; }
.experience-head { display: flex; justify-content: space-between; gap: 60px; align-items: end; margin-bottom: 55px; }
.experience-head h2 { max-width: 700px; }
.experience-head p { color: var(--muted); max-width: 350px; margin: 0; }
.job-card {
  padding: 48px 0; border-top: 1px solid var(--line);
}
.job-card:last-child { border-bottom: 1px solid var(--line); }
.job-card.featured { padding-top: 8px; }
.job-meta { color: var(--muted); font-size: 10px; letter-spacing: .14em; font-weight: 800; padding: 0 0 20px; }
.job-main { display: flex; justify-content: space-between; gap: 30px; }
.job-main h3 { font-size: clamp(27px,3vw,40px); }
.job-main h4 { font-size: 17px; color: var(--accent); margin-top: 9px; letter-spacing: 0; }
.job-index { font: 700 13px "Manrope"; color: var(--muted); }
.job-note {
  position: relative;
  color: #c8d2e2;
  max-width: 900px;
  margin: 25px 0 20px;
  padding: 0 0 0 20px;
  font-size: 15px;
  line-height: 1.75;
  letter-spacing: -.01em;
  border-left: 2px solid var(--accent);
}
.job-summary { color: var(--muted); max-width: 760px; margin: 0 0 30px; }
.job-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 22px; }
.job-grid div { background: var(--surface); border: 1px solid var(--line); padding: 20px; border-radius: 15px; }
.job-grid h5 { margin: 0 0 7px; font: 800 13px "Manrope"; color: var(--text); }
.job-grid p { margin: 0; color: var(--muted); font-size: 13px; }
.tech-tags, .tags { display: flex; flex-wrap: wrap; gap: 8px; }
.tech-tags span, .tags span {
  padding: 8px 11px; border: 1px solid var(--line); background: rgba(255,255,255,.025);
  border-radius: 999px; font-size: 12px; color: var(--muted);
}
.skills-section { background: var(--surface); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.skills-grid { display: grid; grid-template-columns: 1fr 1fr; grid-template-areas: "intro commercial" "tools strategy"; gap: 70px 90px; align-items: start; }
.skills-intro { grid-area: intro; }
.skills-grid .skill-block:nth-of-type(2) { grid-area: commercial; }
.skills-grid .skill-block:nth-of-type(3) { grid-area: strategy; }
.skills-grid .skill-block:nth-of-type(4) { grid-area: tools; }
.skills-intro p { color: var(--muted); max-width: 350px; margin-top: 25px; }
.skill-block { border-top: 1px solid var(--line); padding-top: 18px; }
.skill-block h3 { font-size: 16px; margin-bottom: 18px; letter-spacing: -.02em; }
.education-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.education-card { padding: 32px; background: var(--surface); border: 1px solid var(--line); border-radius: 18px; }
.edu-year { color: var(--accent); font-size: 10px; letter-spacing: .14em; font-weight: 800; }
.education-card h3 { font-size: 25px; margin-top: 24px; }
.education-card p { color: var(--muted); margin: 8px 0 18px; }
.education-card strong { display: block; }
.education-card small { color: var(--muted); }
.community { border-top: 1px solid var(--line); }
.community-grid { display: grid; grid-template-columns: .9fr 1.1fr; gap: 100px; }
.volunteering-title {
  font-size: 16px;
  margin: 0 0 26px;
  letter-spacing: -.02em;
}

.community-item { display: grid; grid-template-columns: 35px 1fr; gap: 15px; padding: 0 0 28px; margin-bottom: 28px; border-bottom: 1px solid var(--line); }
.community-item > span { color: var(--accent); font-size: 11px; font-weight: 800; }
.community-item h3 { font-size: 19px; letter-spacing: -.02em; }
.community-item p { color: var(--muted); font-size: 14px; margin-bottom: 0; }
.contact { background: var(--accent); color: #091007; padding: 105px 0 80px; }
.contact .section-label { color: #30480f; }
.contact h2 { max-width: 700px; }
.contact > .container > p, .contact-inner > p { max-width: 650px; font-size: 17px; color: #304016; }
.contact-actions { display: flex; gap: 12px; margin-top: 28px; }
.contact-details { display: flex; gap: 25px; flex-wrap: wrap; margin-top: 50px; padding-top: 20px; border-top: 1px solid rgba(9,16,7,.2); font-size: 13px; font-weight: 700; }
.footer { padding: 25px 0; color: var(--muted); font-size: 11px; }
.reveal { opacity: 0; transform: translateY(18px); transition: opacity .7s ease, transform .7s ease; }
.reveal.visible { opacity: 1; transform: translateY(0); }
.delay-1 { transition-delay: .1s; }
.delay-2 { transition-delay: .2s; }

@media (max-width: 900px) {
  .nav-links { display: none; }
  .hero { grid-template-columns: 1fr; gap: 45px; padding-top: 65px; }
  .hero-card { max-width: 520px; }
  .about-grid, .community-grid { grid-template-columns: 1fr; gap: 45px; }
  .metrics { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .metric { border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
  .metric:nth-child(2n) { border-right: 0; }
  .metric:last-child { border-right: 0; }
  .experience-head { display: block; }
  .experience-head p { margin-top: 20px; }
  .skills-grid { grid-template-columns: 1fr; grid-template-areas: "intro" "commercial" "strategy" "tools"; gap: 35px; }
}
@media (max-width: 600px) {
  .container { width: min(calc(100% - 30px), var(--max)); }
  .nav { height: 66px; }
  .nav-cta { font-size: 12px; }
  .hero { min-height: auto; padding: 60px 0 75px; }
  h1 { font-size: 50px; }
  .hero-sub { font-size: 15px; }
  .hero-text { font-size: 15px; }
  .hero-actions { flex-direction: column; align-items: stretch; }
  .quick-links { align-items: flex-start; flex-direction: column; gap: 10px; margin-top: 22px; }
  .quick-links .quick-separator { display: none; }
  .quick-links a { line-height: 1.4; }
  .section { padding: 85px 0; }
  .metrics { grid-template-columns: 1fr 1fr; }
  .metric { padding: 30px 14px; }
  .metric:first-child { padding-left: 0; }
  .metric strong { font-size: 34px; }
  .job-grid, .education-grid { grid-template-columns: 1fr; }
  .job-meta { display: block; }
  .job-meta span { display: block; margin-bottom: 5px; }
  .job-main h3 { font-size: 27px; }
  .orb { width: 135px; height: 135px; font-size: 42px; }
  .footer { display: block; }
  .footer span { display: block; margin-bottom: 8px; }
}


.photo-orb { overflow: hidden; position: relative; }
.photo-orb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  display: block;
  font-size: 0;
  color: transparent;
}

/* Professional portrait treatment */
.hero-card .photo-orb {
  width: 230px;
  height: 285px;
  margin: 12px auto 0;
  border-radius: 26px;
  overflow: hidden;
  position: relative;
  background: #171b22;
  box-shadow: 0 24px 70px rgba(0,0,0,.28);
}
.hero-card .photo-orb img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center 16%;
}
@media (max-width: 600px) {
  .hero-card .photo-orb {
    width: 190px;
    height: 235px;
    border-radius: 22px;
  }
}

/* Full supplied profile photo */
.hero-card .photo-orb {
  width: 280px;
  height: 280px;
  margin: 12px auto 0;
  border-radius: 22px;
  overflow: hidden;
  position: relative;
  background: #171b22;
}
.hero-card .photo-orb img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  object-position: center;
}
@media (max-width: 600px) {
  .hero-card .photo-orb {
    width: 240px;
    height: 240px;
  }
}

/* Notable clients & partnerships */
.clients-section { border-top: 1px solid var(--line); }
.clients-head {
  display: grid; grid-template-columns: 1fr .7fr; gap: 70px;
  align-items: end; margin-bottom: 48px;
}
.clients-head h2 { font-size: clamp(36px, 4.5vw, 60px); }
.clients-head p { color: var(--muted); margin: 0; max-width: 420px; }
.logo-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.logo-card {
  min-height: 150px; padding: 24px; border: 1px solid var(--line);
  border-radius: 18px; background: var(--surface); display: flex;
  flex-direction: column; align-items: center; justify-content: center; gap: 18px;
  transition: transform .2s ease, border-color .2s ease, background .2s ease;
}
.logo-card:hover {
  transform: translateY(-3px); border-color: rgba(184,255,92,.35);
  background: var(--surface-2);
}
.logo-card img { width: 100%; height: 62px; object-fit: contain; display: block; }
.logo-card span { color: var(--muted); font-size: 12px; text-align: center; font-weight: 600; }
@media (max-width: 900px) {
  .clients-head { grid-template-columns: 1fr; gap: 20px; }
  .logo-grid { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 600px) {
  .logo-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
  .logo-card { min-height: 125px; padding: 15px; }
  .logo-card img { height: 52px; }
}

/* Personal portfolio refinements */
.impact-intro { display:flex; align-items:baseline; gap:18px; padding: 0 0 28px; }
.impact-intro strong { font: 800 18px "Manrope"; letter-spacing:-.02em; }
.impact-intro span { color:var(--muted); font-size:14px; max-width:760px; }
.job-highlights { display:flex; flex-wrap:wrap; gap:28px; margin-top:22px; }
.job-highlights span { color:var(--muted); font-size:12px; }
.job-highlights strong { color:var(--text); font:800 18px "Manrope"; margin-right:5px; }
.beyond-intro { color:var(--muted); max-width:440px; margin-top:24px; font-size:15px; line-height:1.75; }
@media (max-width:900px) {
  .impact-intro { display:block; }
  .impact-intro span { display:block; margin-top:8px; }
}
@media (max-width:600px) {
  .job-highlights { gap:14px 22px; }
  .job-highlights span { font-size:11px; }
}

/* Desktop spacing refinement: keep Experience and Clients visually connected */
@media (min-width: 901px) {
  #experience { padding-bottom: 55px; }
  #clients { padding-top: 70px; }
}


/* Selected projects */
.projects-section { border-top: 1px solid var(--line); }
.projects-head { display: grid; grid-template-columns: 1fr .7fr; align-items: end; gap: 70px; margin-bottom: 42px; }
.projects-head h2 { font-size: clamp(36px, 4.5vw, 60px); max-width: 650px; }
.projects-head p { color: var(--muted); margin: 0; max-width: 440px; }
.projects-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.project-card { display: flex; flex-direction: column; align-items: flex-start; min-height: 270px; padding: 25px; border: 1px solid var(--line); border-radius: 18px; background: linear-gradient(145deg, rgba(255,255,255,.045), rgba(255,255,255,.012)); transition: transform .22s ease, border-color .22s ease, background .22s ease; }
.project-card:hover { transform: translateY(-4px); border-color: rgba(184,255,92,.48); background: linear-gradient(145deg, rgba(184,255,92,.07), rgba(255,255,255,.015)); }
.project-card-top { display: flex; justify-content: space-between; width: 100%; color: var(--accent); font-size: 11px; font-weight: 800; letter-spacing: .14em; }
.project-arrow { font-size: 18px; line-height: 1; }
.project-card h3 { font-size: clamp(20px, 2vw, 25px); margin: 25px 0 12px; letter-spacing: -.035em; }
.project-card p { color: var(--muted); font-size: 14px; line-height: 1.7; margin: 0 0 18px; }
.project-type { color: #c8d2e2; font-size: 11px; letter-spacing: .03em; margin-top: auto; }
.project-link { color: var(--accent); font-size: 12px; font-weight: 800; margin-top: 20px; }
.project-link span { margin-left: 5px; }
@media (max-width: 900px) { .projects-head { grid-template-columns: 1fr; gap: 20px; } }
@media (max-width: 600px) { .projects-grid { grid-template-columns: 1fr; gap: 12px; } .project-card { min-height: 0; padding: 22px; } .project-card h3 { margin-top: 20px; } }


/* Midnight gradient theme: restrained cobalt lighting + acid-lime highlights */
:root {
  --bg: #030407;
  --surface: #080D18;
  --surface-2: #0B1530;
  --line: rgba(137,164,205,.16);
  --text: #F4F6FA;
  --muted: #A6B4C8;
  --accent: #D4FF24;
  --accent-2: #1558C9;
}
body {
  background-color: var(--bg);
  /* The texture image is shown at 45% visual opacity through a 55% midnight overlay. */
  background-image:
    radial-gradient(ellipse at 82% 7%, rgba(21,88,201,.12), transparent 30%),
    radial-gradient(ellipse at 4% 34%, rgba(21,88,201,.065), transparent 26%),
    radial-gradient(ellipse at 72% 78%, rgba(21,88,201,.055), transparent 32%),
    linear-gradient(rgba(3,4,7,.55), rgba(3,4,7,.55)),
    url("data:image/jpeg;base64,");
  background-size: auto, auto, auto, auto, cover;
  background-position: center, center, center, center, center;
  background-repeat: no-repeat, no-repeat, no-repeat, no-repeat, no-repeat;
  background-attachment: scroll, scroll, scroll, scroll, fixed;
}
.nav-wrap { background: rgba(3,4,7,.88); }
.brand { border-color: rgba(21,88,201,.48); box-shadow: inset 0 0 18px rgba(21,88,201,.06); }
.nav-links a { transition: color .2s ease; }
.nav-links a:hover, .nav-links a.active { color: var(--accent-2); }
.nav-cta { border: 1px solid rgba(21,88,201,.45); border-radius: 10px; padding: 10px 14px; }
.button-ghost { border-color: rgba(21,88,201,.55); background: rgba(21,88,201,.055); }
.button-ghost:hover { background: rgba(21,88,201,.14); border-color: var(--accent-2); }
.hero { position: relative; isolation: isolate; }
.hero::before {
  content: ""; position: absolute; z-index: -1; pointer-events: none;
  width: 48vw; height: 48vw; max-width: 700px; max-height: 700px;
  right: -8%; top: 3%; border-radius: 50%;
  background: radial-gradient(circle, rgba(21,88,201,.13) 0%, rgba(21,88,201,.055) 36%, transparent 70%);
  filter: blur(8px);
}
.hero-card {
  border-color: rgba(21,88,201,.32);
  background: linear-gradient(145deg, rgba(11,21,48,.58), rgba(8,13,24,.68) 48%, rgba(3,4,7,.72));
  box-shadow: 0 24px 80px rgba(0,0,0,.25), 0 0 36px rgba(21,88,201,.055);
}
.impact {
  background: linear-gradient(115deg, rgba(8,13,24,.78), rgba(6,10,19,.84) 56%, rgba(8,17,36,.76));
}
.metric { border-right-color: rgba(21,88,201,.20); }
.job-card { border-top-color: rgba(137,164,205,.15); }
.job-note { border-left-color: var(--accent-2); }
.job-main h4 { color: var(--accent); }
.job-grid div, .education-card {
  background: linear-gradient(145deg, rgba(11,21,48,.44), rgba(8,13,24,.72));
  border-color: rgba(21,88,201,.20);
}
.tech-tags span, .tags span { border-color: rgba(21,88,201,.22); background: rgba(11,21,48,.26); }
.skills-section {
  background: linear-gradient(110deg, rgba(8,13,24,.94), rgba(5,8,15,.98));
}
.logo-card, .project-card {
  background: linear-gradient(145deg, rgba(11,21,48,.42), rgba(8,13,24,.64) 55%, rgba(3,4,7,.72));
  border-color: rgba(21,88,201,.24);
}
.logo-card:hover {
  border-color: rgba(21,88,201,.68);
  background: linear-gradient(145deg, rgba(21,88,201,.12), rgba(8,13,24,.78));
}
.project-card:hover {
  border-color: rgba(21,88,201,.72);
  background: linear-gradient(145deg, rgba(21,88,201,.12), rgba(11,21,48,.45));
}
.project-card-top, .project-link, .contact-icon { color: var(--accent-2); }
.section#about { background: linear-gradient(180deg, rgba(8,13,24,.18), transparent 65%); }
.section#experience { background: linear-gradient(180deg, transparent, rgba(8,13,24,.16)); }
.section#projects { background: linear-gradient(120deg, rgba(8,13,24,.2), transparent 70%); }
