@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

/* Contact section contrast fix: retain the dark midnight theme and use cobalt/lime as accents. */
#contact {
  color: var(--text);
  background: linear-gradient(115deg, rgba(8,13,24,.96), rgba(5,8,15,.98) 58%, rgba(11,21,48,.92));
  border-top: 1px solid rgba(21,88,201,.22);
  border-bottom: 1px solid rgba(21,88,201,.18);
}
#contact .section-label { color: var(--accent); }
#contact h2 { color: var(--text); }
#contact > .container > p,
#contact .contact-inner > p { color: var(--muted); }
#contact .contact-details {
  color: var(--muted);
  border-top-color: rgba(166,180,200,.20);
}
#contact .contact-details a { color: var(--muted); overflow-wrap: anywhere; }
#contact .contact-details a:hover { color: var(--text); }
#contact .button-light {
  background: rgba(21,88,201,.10);
  color: var(--text);
  border-color: rgba(21,88,201,.50);
}
#contact .button-light:hover {
  background: rgba(21,88,201,.20);
  border-color: var(--accent-2);
}
#contact .button-primary { color: #101500; }

/* FIX: keep the uploaded blue texture visibly layered behind the full site. */
html { background: #030407 !important; }
body {
  position: relative;
  background: transparent !important;
  isolation: isolate;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(3, 4, 7, 0.55), rgba(3, 4, 7, 0.55)),
    url("data:image/jpeg;base64,");
  background-size: cover, cover;
  background-position: center, center;
  background-repeat: no-repeat, no-repeat;
  opacity: 1;
}



/* Editorial polish: make Experience and Clients feel like designed portfolio features */
#experience .experience-head { margin-bottom: 44px; }
#experience .experience-head h2 { max-width: 820px; }
#experience .job-card {
  position: relative;
  margin: 0 0 22px;
  padding: 34px 36px 30px;
  border: 1px solid rgba(21, 88, 201, .38);
  border-radius: 22px;
  background: linear-gradient(135deg, rgba(3, 9, 22, .88), rgba(5, 18, 40, .70));
  box-shadow: 0 18px 48px rgba(0, 0, 0, .16), inset 0 1px 0 rgba(255,255,255,.025);
  overflow: hidden;
  transition: border-color .25s ease, transform .25s ease, background .25s ease;
}
#experience .job-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: linear-gradient(180deg, #1558C9 0%, rgba(21,88,201,.12) 100%);
}
#experience .job-card:hover {
  transform: translateY(-3px);
  border-color: rgba(21, 88, 201, .72);
  background: linear-gradient(135deg, rgba(4, 12, 28, .94), rgba(7, 26, 56, .80));
}
#experience .job-card.featured { padding-top: 32px; }
#experience .job-meta { display: flex; justify-content: space-between; gap: 18px; flex-wrap: wrap; color: #a8bad3; }
#experience .job-main { align-items: flex-start; }
#experience .job-main h3 { max-width: 950px; line-height: 1.14; letter-spacing: -.045em; }
#experience .job-main h4 { font-size: 19px; }
#experience .job-index {
  display: grid; place-items: center; flex: 0 0 42px; width: 42px; height: 42px;
  border: 1px solid rgba(21,88,201,.65); border-radius: 13px; color: #76aaff;
  background: rgba(21,88,201,.10); font-size: 12px;
}
#experience .job-note {
  max-width: 100%; margin: 26px 0 22px; padding: 16px 20px;
  border: 1px solid rgba(21,88,201,.24); border-left: 2px solid #1558C9;
  border-radius: 0 13px 13px 0; background: rgba(5,16,35,.48); color: #c5d1e2;
}
#experience .job-summary { max-width: 900px; }
#experience .job-grid { gap: 12px; }
#experience .job-grid div {
  border-radius: 14px; border-color: rgba(21,88,201,.24);
  background: linear-gradient(145deg, rgba(10,25,49,.72), rgba(4,11,24,.72));
}
#experience .job-highlights { gap: 10px; }
#experience .job-highlights span {
  display: inline-flex; align-items: baseline; gap: 5px; padding: 10px 13px;
  border: 1px solid rgba(21,88,201,.28); border-radius: 11px;
  background: rgba(4,13,29,.62); color: #aebed3;
}
#experience .job-highlights strong { color: #d4ff27; }

#clients .clients-head { align-items: center; margin-bottom: 38px; }
#clients .clients-head p {
  max-width: 490px; padding: 20px 22px; border-left: 2px solid #1558C9;
  border-radius: 0 14px 14px 0; background: linear-gradient(110deg, rgba(21,88,201,.12), rgba(4,12,27,.35));
}
#clients .logo-grid { gap: 15px; align-items: stretch; }
#clients .logo-card {
  position: relative; min-height: 166px; padding: 25px 22px;
  border-color: rgba(21,88,201,.28); border-radius: 18px;
  background: linear-gradient(145deg, rgba(4,12,27,.90), rgba(5,18,39,.74));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.025);
  overflow: hidden;
}
#clients .logo-card::after {
  content: ""; position: absolute; right: -28px; top: -36px; width: 90px; height: 90px;
  border: 1px solid rgba(21,88,201,.16); border-radius: 50%; pointer-events: none;
}
#clients .logo-card:hover {
  transform: translateY(-5px); border-color: rgba(21,88,201,.78);
  background: linear-gradient(145deg, rgba(5,15,34,.96), rgba(7,29,63,.88));
  box-shadow: 0 15px 34px rgba(0,0,0,.22), 0 0 0 1px rgba(21,88,201,.08);
}
#clients .logo-card img { position: relative; z-index: 1; height: 68px; transition: transform .25s ease; }
#clients .logo-card:hover img { transform: scale(1.045); }
#clients .logo-card span { position: relative; z-index: 1; color: #bdc9da; font-size: 12px; letter-spacing: .015em; }
@media (min-width: 901px) {
  #clients .logo-card:nth-child(1) { grid-column: span 2; }
  #clients .logo-card:nth-child(1) img { height: 76px; }
}
@media (max-width: 900px) {
  #experience .job-card { padding: 28px 24px 25px; }
  #clients .logo-card { min-height: 145px; }
}
@media (max-width: 600px) {
  #experience .job-card { padding: 23px 18px 22px; border-radius: 17px; }
  #experience .job-main { gap: 12px; }
  #experience .job-main h3 { font-size: 25px; }
  #experience .job-index { flex-basis: 35px; width: 35px; height: 35px; }
  #experience .job-note { padding: 13px 14px; font-size: 13px; }
  #experience .job-highlights span { padding: 8px 10px; }
  #clients .logo-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
  #clients .logo-card { min-height: 128px; padding: 15px 10px; }
  #clients .logo-card img { height: 48px; }
  #clients .logo-card:nth-child(1) { grid-column: span 2; }
  #clients .logo-card:nth-child(1) img { height: 58px; }
}



