/* Layout refinement: reduce oversized vertical gaps on desktop */
@media (min-width: 901px) {
  .section { padding-top: 78px; padding-bottom: 78px; }
  .section-label { margin-bottom: 26px; }
  .hero { min-height: min(790px, calc(100vh - 76px)); padding-top: 44px; padding-bottom: 48px; }
  .experience-head { margin-bottom: 34px; }
  #experience .experience-head { margin-bottom: 34px; }
  #clients .clients-head { margin-bottom: 30px; }
