/* Reference-inspired desktop layout: compact hero, immediate client strip, dense experience metrics */
:root { --max: 1360px; }
.nav.container, .container { width: min(var(--max), calc(100% - 64px)); }
.hero { min-height: auto; grid-template-columns: 1.05fr .95fr; gap: 48px; padding-top: 34px; padding-bottom: 34px; }
h1 { font-size: clamp(48px, 4.2vw, 66px); line-height: .99; max-width: 800px; }
.hero-sub { margin-top: 18px; }
.hero-text { font-size: 15px; line-height: 1.55; margin: 14px 0 0; }
.hero-card { min-height: 0; padding: 20px; border-radius: 22px; }
.photo-orb { width: 150px; height: 150px; margin: 14px auto; }
.profile-title { font-size: 25px; line-height: 1.2; }
.hero-card > p { margin: 8px 0 14px; }
.mini-stats { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 0; margin-top: 16px; }
.mini-stats > div { padding: 12px 10px 0; border-top: 1px solid var(--line); border-right: 1px solid var(--line); }
.mini-stats > div:first-child { padding-left: 0; }
.mini-stats > div:last-child { border-right: 0; }
.mini-stats strong { font-size: 21px; }
.mini-stats span { font-size: 11px; line-height: 1.4; }
.clients-section { padding: 22px 0 18px !important; border-top: 1px solid var(--line); }
.clients-section .section-label { margin-bottom: 12px; }
.clients-head { grid-template-columns: 1.2fr .8fr; gap: 32px; margin-bottom: 16px; }
.clients-head h2 { font-size: clamp(30px, 3vw, 42px); }
.clients-head p { font-size: 13px; line-height: 1.55; }
.logo-grid { grid-template-columns: repeat(7,minmax(0,1fr)); gap: 8px; }
.logo-card { min-height: 84px; padding: 10px 12px; border-radius: 12px; gap: 6px; }
.logo-card img { height: 38px; }
.logo-card span { font-size: 10px; line-height: 1.25; }
#experience.section { padding-top: 26px; padding-bottom: 54px; }
#experience .section-label { margin-bottom: 12px; }
.experience-head { display: grid; grid-template-columns: 1.35fr .65fr; gap: 30px; align-items: end; margin-bottom: 20px; }
.experience-head h2 { font-size: clamp(30px, 3vw, 42px); }
.experience-head p { font-size: 13px; line-height: 1.5; }
#experience .job-card { border: 1px solid var(--line); border-radius: 18px; background: rgba(4,12,28,.72); padding: 18px; margin-bottom: 14px; }
#experience .job-card.featured { padding-top: 18px; }
#experience .job-meta { padding-bottom: 12px; }
#experience .job-main h3 { font-size: clamp(22px,2.1vw,30px); }
#experience .job-note { font-size: 13px; line-height: 1.55; max-width: none; margin: 14px 0 4px; }
.fan90-metrics { display: grid; grid-template-columns: repeat(6,minmax(0,1fr)); gap: 7px; margin-top: 14px; }
.fan90-metrics span { display: flex; flex-direction: column; gap: 3px; padding: 9px 10px; border: 1px solid rgba(21,88,201,.65); border-radius: 10px; background: rgba(3,8,20,.78); min-width: 0; }
.fan90-metrics strong { color: var(--accent); font-size: 19px; line-height: 1.1; margin: 0; }
.fan90-metrics small { color: var(--muted); font-size: 10px; line-height: 1.3; }
@media (max-width: 1050px) {
  .logo-grid { grid-template-columns: repeat(4,minmax(0,1fr)); }
  .fan90-metrics { grid-template-columns: repeat(4,minmax(0,1fr)); }
  .hero { gap: 28px; }
}
@media (max-width: 700px) {
  .nav.container, .container { width: min(var(--max), calc(100% - 32px)); }
  .hero { grid-template-columns: 1fr; padding-top: 30px; gap: 24px; }
  h1 { font-size: clamp(38px, 10vw, 54px); }
  .hero-card { max-width: 100%; }
  .mini-stats { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .mini-stats > div:nth-child(2) { border-right: 0; }
  .clients-head, .experience-head { grid-template-columns: 1fr; gap: 10px; }
  .logo-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .fan90-metrics { grid-template-columns: repeat(2,minmax(0,1fr)); }
}


/* Latest refinements: Web Curve metrics and personal photo collage */
.webcurve-metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.webcurve-metrics > span { min-width: 0; }
.webcurve-metrics > span strong { display: block; }
.webcurve-metrics > span small { display: block; line-height: 1.45; margin-top: 4px; }
.beyond-photo-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 14px; margin-top: 30px; align-items: end; }
.beyond-photo { margin: 0; overflow: hidden; position: relative; border: 1px solid rgba(65,139,255,.28); border-radius: 18px; background: rgba(7,15,31,.7); }
.beyond-photo img { display: block; width: 100%; height: 100%; object-fit: cover; }
.beyond-photo-main { height: 300px; }
.beyond-photo-main img { object-position: center 28%; }
.beyond-photo-detail { height: 220px; transform: translateY(16px); }
.beyond-photo-detail img { object-position: center 18%; transform: scale(1.22); }
.beyond-photo figcaption { position: absolute; left: 12px; bottom: 12px; padding: 7px 10px; border-radius: 8px; background: rgba(3,8,18,.78); color: #e8edf5; font-size: 11px; letter-spacing: .04em; }
@media (max-width: 900px) {
  .webcurve-metrics { grid-template-columns: repeat(3, minmax(0,1fr)); }
  .beyond-photo-main { height: 250px; }
  .beyond-photo-detail { height: 190px; }
}
@media (max-width: 600px) {
  .webcurve-metrics { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .beyond-photo-grid { grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 22px; }
  .beyond-photo-main { height: 210px; }
  .beyond-photo-detail { height: 165px; transform: translateY(8px); }
  .beyond-photo figcaption { font-size: 9px; left: 7px; bottom: 7px; padding: 5px 6px; }
}


.beyond-photo-grid-three { grid-template-columns: 1.08fr .92fr; grid-template-rows: auto auto; align-items: stretch; }
.beyond-photo-grid-three .beyond-photo-main { grid-column: 1; grid-row: 1; height: 255px; }
.beyond-photo-grid-three .beyond-photo-detail { grid-column: 2; grid-row: 1; height: 215px; transform: translateY(24px); }
.beyond-photo-grid-three .beyond-photo-third { grid-column: 1 / span 2; height: 235px; width: 78%; margin: 10px auto 0; }
.beyond-photo-grid-three .beyond-photo-third img { object-position: center 48%; }
@media (max-width: 900px) { .beyond-photo-grid-three .beyond-photo-main { height: 230px; } .beyond-photo-grid-three .beyond-photo-detail { height: 195px; } .beyond-photo-grid-three .beyond-photo-third { height: 210px; width: 90%; } }
@media (max-width: 600px) { .beyond-photo-grid-three { grid-template-columns: 1fr 1fr; gap: 10px; } .beyond-photo-grid-three .beyond-photo-main { height: 190px; } .beyond-photo-grid-three .beyond-photo-detail { height: 175px; transform: translateY(10px); } .beyond-photo-grid-three .beyond-photo-third { grid-column: 1 / span 2; width: 100%; height: 190px; margin-top: 0; } .beyond-photo figcaption { font-size: 10px; max-width: calc(100% - 24px); } }
